/**
 * @internal
 */
export function getBrowserTypeDisplayName(
  browserType: InstalledBrowser,
): string {
  switch (browserType) {
    case InstalledBrowser.FIREFOX:
    case InstalledBrowser.CHROME:
      return browserType.charAt(0).toUpperCase() + browserType.slice(1);
    default:
      return browserType;
  }
