      if (this.onclose) {
        this.onclose.call(null);
      }
    });
    // Silently log all errors - we don't know what to do with them.
    this.#ws.addEventListener('error', debugCatchError);
  }

  send(message: string): void {
    this.#ws.send(message);
  }

