61: function createTransformStream(
62:   child: ChildProcessByStdio<Writable, Readable, null>,
63: ): Transform {
64:   const stream = new Stream.Transform({
65:     transform(chunk, encoding, callback) {
66:       if (!child.stdin.write(chunk, encoding)) {
67:         child.stdin.once('drain', callback);
68:       } else {
69:         callback();
70:       }
71:     },
72: 
73:     flush(callback) {
74:       if (child.stdout.destroyed) {
75:         callback();
76:       } else {
77:         child.stdin.end();
78:         child.stdout.on('close', callback);
79:       }
80:     },
81:   });
82: 
83:   child.stdin.on('error', e => {
84:     if ('code' in e && e.code === 'EPIPE') {
85:       // finished before reading the file finished (i.e. head)
86:       stream.emit('end');
87:     } else {
88:       stream.destroy(e);
89:     }
90:   });
91: 
92:   child.stdout
93:     .on('data', data => {
94:       return stream.push(data);
95:     })
96:     .on('error', e => {
97:       return stream.destroy(e);
98:     });
99: 
100:   child.once('close', () => {
101:     return stream.end();
102:   });
103: 
104:   return stream;
105: }
